public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    long n = sc.nextLong();
    long goodCount = 0;

    for (long i = 1; i <= n; i++) {
        long sumOfDigits = 0;
        long number = i;

        while (number > 0) {
            sumOfDigits += number % 10;
            number /= 10;
        }

        if (i % sumOfDigits == 0) {
            goodCount++;
        }
    }

    System.out.println(goodCount);
}
